/**
 * Room codes are generated by the database with an unambiguous alphabet
 * (no 0/O, 1/I/L). Keep this in sync with the CHECK constraint in
 * supabase/migrations/20261023000100_init.sql and generate_room_code() in
 * 20261023000200_game_rpcs.sql.
 */
export const ROOM_CODE_LENGTH = 6;
export const ROOM_CODE_ALPHABET = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';

const ROOM_CODE_CHARS = new Set(ROOM_CODE_ALPHABET.split(''));

export const ROOM_CODE_PATTERN = /^[ABCDEFGHJKMNPQRSTUVWXYZ23456789]{6}$/;

/** Uppercase, drop characters that cannot appear in a code, cap at 6. */
export function sanitizeRoomCode(value: string): string {
  return Array.from(value.toUpperCase())
    .filter((character) => ROOM_CODE_CHARS.has(character))
    .join('')
    .slice(0, ROOM_CODE_LENGTH);
}

export function isValidRoomCode(value: string): boolean {
  return ROOM_CODE_PATTERN.test(value);
}
